const now = new Date();
const hour = now.getHours();
const vardiyaTuru = hour < 12 ? 'GECE_VARDIYASI_DEVRI (20:00 - 08:00)' : 'GUNDUZ_VARDIYASI_DEVRI (08:00 - 20:00)';
const tarih = now.toLocaleDateString('tr-TR');

const devirOzeti = {
  nobetciAmir: 'Özel Güvenlik Vardiya Amiri',
  devralanAmir: 'Gündüz Vardiya Amiri',
  toplamZiyaretci: 42,
  teslimAlinanKargo: 18,
  teslimEdilenKargo: 15,
  bekleyenKargo: 3,
  geceDevriyesiTurNoktalari: '%100 Eksiksiz (14/14 Nokta Okutuldu)',
  vukuatDurumu: 'TEMIZ (Herhangi bir asayiş, tartışma veya şüpheli olay yaşanmamıştır)',
  otoparkBariyerDurumu: 'Normal Çalışıyor',
  teslimEdilenDemirbaslar: '4 Adet El Telsizi, 2 Adet Devriye Tur Kalemi, 1 Adet Anahtar Panosu'
};

return [{
  json: {
    timestamp: now.toISOString(),
    tarih,
    vardiyaTuru,
    devirOzeti,
    summary: `${tarih} ${vardiyaTuru}: 5188 Özel Güvenlik ve Tesis Devir Tutanakları Başarıyla Kaydedildi.`
  }
}];
